"""Semantic native-provider declaration for packed gated-delta computation."""

from __future__ import annotations

from dataclasses import dataclass, field

from kestrel_kernels.native_coverage import (
    KernelDemand,
    NativeResolution,
    NativeTarget,
    ProviderResult,
    Rejection,
)


PACKED_GATED_DELTA_OP_KIND = "gated_delta.packed"
SUPPORTED_RECURRENT_SHAPES = ((16, 16, 128), (16, 32, 128), (16, 48, 128))
SUPPORTED_CONV_DIMS = tuple(
    (2 * num_k_heads + num_v_heads) * head_dim
    for num_k_heads, num_v_heads, head_dim in SUPPORTED_RECURRENT_SHAPES
)
SUPPORTED_TARGET_ARCHES = frozenset(
    {"sm80", "sm86", "sm89", "sm90", "sm100", "sm110", "sm120"}
)


def packed_gated_delta_demand(
    input_dtype,
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> KernelDemand:
    return KernelDemand(
        op_kind=PACKED_GATED_DELTA_OP_KIND,
        input_dtype=input_dtype,
        layout="packed_sequence",
        dimensions={
            "head_dim": head_dim,
            "num_k_heads": num_k_heads,
            "num_v_heads": num_v_heads,
        },
    )


@dataclass(frozen=True)
class PackedGatedDeltaProvider:
    name: str = field(default="gated_delta", init=False)
    op_kinds: frozenset[str] = field(
        default=frozenset({PACKED_GATED_DELTA_OP_KIND}),
        init=False,
    )

    def supports_semantics(self, demand: KernelDemand, *, backend: str) -> bool:
        """Whether runtime inputs match this family, without certifying an artifact."""

        if demand.op_kind not in self.op_kinds or backend != "cuda":
            return False
        if demand.input_dtype != "bf16":
            return False
        try:
            shape = tuple(
                demand.dimension(name)
                for name in ("num_k_heads", "num_v_heads", "head_dim")
            )
        except KeyError:
            return False
        return shape in SUPPORTED_RECURRENT_SHAPES

    def resolve(self, demand: KernelDemand, target: NativeTarget) -> ProviderResult:
        if demand.op_kind not in self.op_kinds:
            return Rejection(
                provider=self.name,
                target=target,
                demand=demand,
                code="unsupported_operation",
                reason=f"provider does not implement {demand.op_kind!r}",
            )
        if target.backend != "cuda":
            return Rejection(
                provider=self.name,
                target=target,
                demand=demand,
                code="unsupported_target",
                reason="packed gated delta requires a CUDA target",
            )
        if target.arch not in SUPPORTED_TARGET_ARCHES:
            return Rejection(
                provider=self.name,
                target=target,
                demand=demand,
                code="unsupported_arch",
                reason=f"packed gated delta does not support target arch {target.arch!r}",
                details={"supported_arches": SUPPORTED_TARGET_ARCHES},
            )
        if demand.input_dtype != "bf16":
            return Rejection(
                provider=self.name,
                target=target,
                demand=demand,
                code="unsupported_dtype",
                reason="packed gated delta requires BF16 inputs",
                details={"input_dtype": demand.input_dtype},
            )

        required = ("num_k_heads", "num_v_heads", "head_dim")
        try:
            shape = tuple(demand.dimension(name) for name in required)
        except KeyError as exc:
            return Rejection(
                provider=self.name,
                target=target,
                demand=demand,
                code="missing_dimension",
                reason=f"packed gated delta requires dimension {exc.args[0]!r}",
            )
        if shape not in SUPPORTED_RECURRENT_SHAPES:
            return Rejection(
                provider=self.name,
                target=target,
                demand=demand,
                code="unsupported_shape",
                reason=f"no packed gated-delta implementation for head shape {shape}",
                details={"head_shape": shape},
            )

        num_k_heads, num_v_heads, head_dim = shape
        conv_channels = (2 * num_k_heads + num_v_heads) * head_dim
        return NativeResolution(
            provider=self.name,
            implementation=(
                f"packed_gated_delta_bf16_k{num_k_heads}_v{num_v_heads}_d{head_dim}"
            ),
            target=target,
            demand=demand,
            constraints={"conv_channels": conv_channels},
        )


PACKED_GATED_DELTA_PROVIDER = PackedGatedDeltaProvider()


def resolve_packed_gated_delta(
    *,
    target: NativeTarget,
    input_dtype,
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> ProviderResult:
    demand = packed_gated_delta_demand(
        input_dtype,
        num_k_heads,
        num_v_heads,
        head_dim,
    )
    return PACKED_GATED_DELTA_PROVIDER.resolve(demand, target)


__all__ = [
    "PACKED_GATED_DELTA_OP_KIND",
    "PACKED_GATED_DELTA_PROVIDER",
    "SUPPORTED_CONV_DIMS",
    "SUPPORTED_RECURRENT_SHAPES",
    "SUPPORTED_TARGET_ARCHES",
    "PackedGatedDeltaProvider",
    "packed_gated_delta_demand",
    "resolve_packed_gated_delta",
]
